:root{
  --bg:#07111e; --bg-card:#0d1c30; --bg-card2:#12263f; --border:#1e3552;
  --accent:#7c9eff; --accent2:#6fe09a; --warn:#e0a458;
  --text:#e6eefc; --text-dim:#c7d6ec; --text-faint:#9cb0cf;
  --sidebar-w:296px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--text);overflow-x:hidden;
  font-family:"Noto Sans JP",-apple-system,BlinkMacSystemFont,"Hiragino Kaku Gothic ProN","Yu Gothic","Meiryo",sans-serif;
  font-size:16px;line-height:1.85;-webkit-font-smoothing:antialiased}
.sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sidebar-w);overflow-y:auto;
  background:#0a1626;border-right:1px solid var(--border);padding:24px 16px 40px;z-index:50}
.sidebar-title{font-weight:800;font-size:15px;color:#fff;line-height:1.5;margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid var(--border)}
.sidebar-title span{display:block;font-weight:500;font-size:12.5px;color:var(--text-faint)}
.nav-list,.nav-list ul{list-style:none;margin:0;padding:0}
.nav-list a{display:block;color:var(--text-dim);text-decoration:none;font-size:13.5px;line-height:1.5;padding:6px 10px;border-radius:6px;border-left:2px solid transparent}
.nav-list a:hover{background:#12263f;color:#fff}
.nav-list a.active{background:#162f52;color:#fff;border-left-color:var(--accent)}
.nav-h3 a{font-size:12.5px;padding-left:22px;color:var(--text-faint)}
.nav-toggle{display:none;position:fixed;top:12px;left:12px;z-index:60;background:#12263f;color:#fff;border:1px solid var(--border);border-radius:8px;padding:8px 12px;font:600 13px "Noto Sans JP",sans-serif;cursor:pointer}
.main{margin-left:var(--sidebar-w);padding:48px 56px 80px}
.hero{position:relative;overflow:hidden;background:linear-gradient(135deg,#0d1c30,#0a1626);border:1px solid var(--border);border-radius:16px;padding:36px 36px 28px;margin-bottom:40px}
.hero::before{content:"";position:absolute;top:-120px;right:-120px;width:380px;height:380px;background:radial-gradient(circle,rgba(124,158,255,.28),transparent 65%);pointer-events:none}
.eyebrow{display:inline-block;background:rgba(124,158,255,.14);color:var(--accent);border:1px solid rgba(124,158,255,.4);border-radius:999px;padding:3px 14px;font-size:12.5px;font-weight:700;margin-bottom:14px}
.hero-title{margin:0 0 22px;font-size:28px;font-weight:800;color:#fff;line-height:1.4;position:relative}
.meta-row{display:block;position:relative;border-top:1px solid var(--border)}
.meta-item{display:grid;grid-template-columns:110px 1fr;gap:12px;align-items:baseline;padding:9px 0;border-bottom:1px solid var(--border)}
.meta-item:last-child{border-bottom:none}
.meta-label{font-size:12px;letter-spacing:.08em;color:var(--text-faint);font-weight:700}
.meta-value{font-size:14.5px;color:var(--text)}
h2{font-size:25px;font-weight:800;color:#fff;margin:64px 0 18px;padding-bottom:10px;border-bottom:2px solid var(--border);scroll-margin-top:24px;line-height:1.45}
h2::before{content:"";display:inline-block;width:6px;height:22px;background:var(--accent);border-radius:3px;margin-right:12px;vertical-align:-3px}
h3{font-size:19px;font-weight:700;color:#dbe7ff;margin:38px 0 12px;scroll-margin-top:24px}
p,li{color:var(--text)}
a{color:var(--accent)}
strong{color:#fff}
ul,ol{padding-left:1.4em}
li{margin:4px 0}
code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.88em;background:#12263f;color:#ffd9a0;padding:2px 6px;border-radius:5px;overflow-wrap:break-word;word-break:break-word}
pre{background:#050d18;border:1px solid var(--border);border-radius:10px;padding:16px 18px;overflow-x:auto;line-height:1.6;margin:16px 0}
pre code{background:none;color:#d6e4ff;padding:0;font-size:13.5px;word-break:normal;overflow-wrap:normal}
.table-scroll{overflow-x:auto;margin:18px 0;border:1px solid var(--border);border-radius:10px;background:var(--bg-card)}
table{border-collapse:collapse;width:100%;font-size:14.5px}
th{background:#12263f;color:#fff;text-align:left;font-weight:700;white-space:nowrap}
th,td{padding:10px 14px;border-bottom:1px solid var(--border);vertical-align:top;line-height:1.65}
tr:last-child td{border-bottom:none}
td{color:var(--text)}
td a{overflow-wrap:anywhere;word-break:break-all}
.callout{border:1px solid var(--border);border-left:4px solid var(--accent);background:var(--bg-card);border-radius:10px;padding:14px 20px;margin:20px 0}
.callout p{margin:6px 0}
.callout-tip,.callout-key{border-left-color:var(--accent2);background:#0c2430}
.callout-new{border-left-color:var(--accent)}
.callout-warn{border-left-color:var(--warn);background:#221b10}
.callout-note{border-left-color:#5b7db8}
.mermaid-diagram{display:block;overflow-x:auto;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;padding:20px 16px;margin:22px 0}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.mermaid-diagram p{color:inherit;margin:0}
.page-footer{margin-top:64px;padding-top:20px;border-top:1px solid var(--border);color:var(--text-faint);font-size:13.5px;line-height:1.8}
@media (max-width:900px){
  .sidebar{transform:translateX(-100%);transition:transform .25s}
  .sidebar.open{transform:none;box-shadow:0 0 40px rgba(0,0,0,.6)}
  .nav-toggle{display:block}
  .main{margin-left:0;padding:64px 16px 60px}
  .hero{padding:26px 20px 20px}
  .hero-title{font-size:23px}
  .meta-item{grid-template-columns:1fr;gap:2px}
  h2{font-size:21px}
}
